int 화면글(int धनी_ऑब्जॅक्ट,int वळखुपी_मोल,const uint32_t *डेटा,unsigned आयटम_COUNT){विजीट_स्थिती *너비값=मूलतत्व_मोल(धनी_ऑब्जॅक्ट,वळखुपी_मोल);if(!너비값)return -9;if(आयटम_COUNT>127)return -22;for(unsigned 순번=0;순번<आयटम_COUNT;순번++){unsigned वर्ण_एनकोडिंग=डेटा[순번];if(वर्ण_एनकोडिंग>0x10ffff||(वर्ण_एनकोडिंग>=0xd800&&वर्ण_एनकोडिंग<=0xdfff))return -22;}for(unsigned 순번=0;순번<आयटम_COUNT;순번++)너비값->SMS[순번]=डेटा[순번];너비값->लांबाय_मोल=आयटम_COUNT;if(표시됨(धनी_ऑब्जॅक्ट,너비값))बोर्ड_टर्मिनल(3);return 0;}
